<include file="Public:header"/><link rel="stylesheet" href="{pigcms{$static_path}css/bootstrap.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/font-awesome.min.css?t=01"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-fonts.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace.min.css" id="main-ace-style"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-skins.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-rtl.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/global.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui-timepicker-addon.css"><link rel="stylesheet" href="{pigcms{$static_public}layui2/css/layui.css" media="all"/><script type="text/javascript" src="{pigcms{$static_path}js/bootstrap.min.js"></script><script src="{pigcms{$static_public}kindeditor/kindeditor.js"></script><script src="{pigcms{$static_public}layui2/layui.all.js" charset="utf-8"></script><style>       input[readonly] {            color: #939192;            background: #f5f5f5;            cursor: default        }       .form-group input[readonly] {            color: #939192;            background: #f5f5f5;            cursor: default        }    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }   .input{ width: 300px;height: 30px;    line-height: 30px;}    .right_div{        display: inline-block;    margin-left: 50px;    }    .ant-btn {        line-height: 1.499;        position: relative;        display: inline-block;        font-weight: 400;        white-space: nowrap;        text-align: center;        background-image: none;        border: 1px solid transparent;        -webkit-box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        cursor: pointer;        -webkit-transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        -webkit-user-select: none;        -moz-user-select: none;        -ms-user-select: none;        user-select: none;        -ms-touch-action: manipulation;        touch-action: manipulation;        height: 32px;        padding: 0 15px;        font-size: 14px;        border-radius: 2px;        color: #fff;        background-color: #1890ff;        text-shadow: 0 -1px 0 rgb(0 0 0 / 12%);}</style>	<div class="mainbox" style="background-color: #fff;min-height: 590px;">       <div class="tabbable" style="height: 60px;">            <ul id="myTab" class="nav nav-tabs" style="height: 35px;margin-top:0px;">                <li <if condition="$getparam['activetab'] neq 'datalist'">class="active"</if> >                    <a href="javascript:;" data-toggle="tab" onclick="toggleNavTab('basicinfo_div')">{pigcms{$block_type_str}设置</a>                </li>                <php>                 $getTmpparam=$_GET;                 $getTmpparam['activetab']='datalist';                </php>                <li <if condition="$getparam['activetab'] eq 'datalist'">class="active"</if> >                    <a href="{pigcms{:U('House/house_nav_2list',$getTmpparam)}" class="on">{pigcms{$block_type_str}列表</a>                </li>            </ul>        </div>      <div id="basicinfo_div" class="tab_div <if condition="$getparam['activetab'] eq 'datalist'">hide</if>" >        <input type="hidden" class="input set_input" name="block_type_id" value="{pigcms{$block_type_id}"/>        <input type="hidden" class="input set_input" name="village_id" value="{pigcms{$village_id}"/>        <if condition="in_array($block_type_id,array('left_bottom_rowgrid','right_bottom_rowgrid'))">        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>是否显示</label></label>            <div class="radio" style="padding-top: 5px;">                <label style="padding-left:0px;padding-right:20px;"><input name="is_show" value="1" type="radio" class="ace set_input"  <if condition="$nav_set AND $nav_set.is_show eq 1">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;开启</span></label>                <label style="padding-left:0px;"><input name="is_show" value="0" type="radio" class="ace set_input" <if condition="empty($nav_set) OR ($nav_set AND $nav_set.is_show eq 0)">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;关闭</span></label>            </div>        </div>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>矩形背景颜色：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input-text set_input" name="block_bg_color" id="config_block_bgcolor" value="{pigcms{$nav_set.block_bg_color}" readonly="readonly" style="text-indent:1000px;width:60px;height: 30px;cursor:default;background-color:{pigcms{$nav_set.block_bg_color} !important"/>                <a href="javascript:void(0);" id="choose_color_box_block_bgtxt" style="line-height:28px;">点击选择颜色</a>                            </div>        </div>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>矩形边框颜色：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input-text set_input" name="block_border_color" id="config_block_bordercolor" value="{pigcms{$nav_set.block_border_color}" readonly="readonly" style="text-indent:1000px;width:60px;height: 30px;cursor:default;background-color:{pigcms{$nav_set.block_border_color} !important"/>                <a href="javascript:void(0);" id="choose_color_box_block_bordertxt" style="line-height:28px;">点击选择颜色</a>                            </div>        </div>        <div class="form-group">                <label class="col-sm-1" style="width: 15%;"><label>圆角半径:</label></label>				<div id="slideTest1" style="width: 100px;display: inline-block"></div>				<div style="display: inline-block;margin-left: 15px">					<input type="number" class="input set_input" id="fillet_radius" style="width: 60px;margin-right: 20px" name="fillet_radius" min="0" max="50" size="20" value="{pigcms{$nav_set.fillet_radius}"/>					<span>圆角半径默认为0,最大设置为50,圆角半径值越大，圆角越圆，0是为直角。</span>				</div>         </div>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label class="red">*标题：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" id="set_input_title" name="title" value="{pigcms{$nav_set.title}" placeholder="6个汉字以内" maxlength="6" required /> &nbsp;&nbsp;&nbsp;(必填项)            </div>        </div>       <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>副标题：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" name="sub_title" value="{pigcms{$nav_set.sub_title}" placeholder="15个汉字以内" maxlength="15"/>            </div>        </div>            <div class="form-group">                <label class="col-sm-1" style="width: 15%;"><label for="label_img_up">角标图片上传：</label></label>                <div class="radio" style="padding-top: 5px;">                <input class="btn btn-primary" type="button" id="label_img_up" value="选择图片" style="line-height: 8px;" />                <input type="hidden"  class="set_input" name="label_img" value="{pigcms{$nav_set.label_img}" id="label_img" />                <span id="label_img_div" style="position: relative;margin-top: 20px; <if condition="!$nav_set['label_img']">display: none;</if>">                <img src="{pigcms{:replace_file_domain($nav_set['label_img'])}" id="label_img_view"  class="view_msg" style="cursor: pointer;margin-left: 10px; width: 100px; <if condition="!$nav_set['label_img']">display: none;</if>">                  <span style="position: relative; top: -32px;left: -10px;display: inline-block;padding: 7px;font-size: 16px;background-color: #f5f5f5cf;border-radius: 30px;cursor: pointer;" onclick="delsetimg()">X</span>                </span>                <span class="form_tips">建议上传70*70的图片</span>                </div>            </div>        <else />       <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label class="red">*标题：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" id="set_input_title" name="title" value="{pigcms{$nav_set.title}" placeholder="6个汉字以内" maxlength="6" required /> &nbsp;&nbsp;&nbsp;(必填项)            </div>        </div>       <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>副标题：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" name="sub_title" value="{pigcms{$nav_set.sub_title}" placeholder="15个汉字以内" maxlength="15"/>            </div>        </div>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>角标名称：</label></label>            <div class="radio" style="padding-top: 5px;">                <input type="text" class="input set_input" name="label_title" value="{pigcms{$nav_set.label_title}" placeholder="7个汉字以内" maxlength="7"/>                 <div class="right_div">                        <span>角标背景颜色：</span>                        <input type="text" class="input-text set_input" name="label_bg_color" id="config_labelcolor" value="{pigcms{$nav_set.label_bg_color}" readonly="readonly" style="text-indent:1000px;width:60px;height: 30px;cursor:default;background-color:{pigcms{$nav_set.label_bg_color} !important"/>                        <a href="javascript:void(0);" id="choose_color_box_labeltxt" style="line-height:28px;">点击选择颜色</a>                    </div>            </div>        </div>        <div class="form-group">                <label class="col-sm-1" style="width: 15%;"><label>圆角半径:</label></label>				<div id="slideTest1" style="width: 100px;display: inline-block"></div>				<div style="display: inline-block;margin-left: 15px">					<input type="number" class="input set_input" id="fillet_radius" style="width: 52px;margin-right: 20px" name="fillet_radius" min="0" max="50" size="20" value="{pigcms{$nav_set.fillet_radius}"/>					<span>圆角半径默认为0,最大设置为50,圆角半径值越大，圆角越圆，0是为直角。</span>				</div>         </div>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>是否显示系统导航</label></label>            <div class="radio" style="padding-top: 5px;">                <label style="padding-left:0px;padding-right:20px;"><input name="show_community_platform" value="1" type="radio" class="ace set_input"  <if condition="$nav_set AND $nav_set.show_community_platform eq 1">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;开启</span></label>                <label style="padding-left:0px;"><input name="show_community_platform" value="0" type="radio" class="ace set_input" <if condition="empty($nav_set) OR $nav_set.show_community_platform eq 0">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;关闭</span></label>            </div>        </div>        </if>            <div style="text-align:center;margin-top: 50px;">               <button type="button" onclick="saveNavSetData()" class="ant-btn ant-btn-primary" >保存设置</button>           </div>        </div>        <div id="datalist_div" class="tab_div <if condition="$getparam['activetab'] neq 'datalist'">hide</if>">        <if condition="in_array($block_type_id,array('village_life_service','village_life_assistant'))">        <div style="margin-left: 10px;color: #9a9999">            <span> 是否显示系统导航开关 说明：</span>            <p> 1、当开关是开启状态下，即默认小区里的正常导航大于或等于12个的时候显示的只有小区导航，如果小于12个则追加系统导航。</p>            <p>2、如果是关闭状态下，则无论小区里正常的导航有多少个都不会追加系统导航。</p>        </div>        </if>         <if condition="in_array($block_type_id,array('left_bottom_rowgrid','right_bottom_rowgrid'))">          <div style="margin-left: 10px;color: #9a9999">                <span> 说明：</span>                <p>1、广告建议尺寸：260*108  平台已为你添加0 张。</p>                <p> 2、添加的广告图，用户端只展示最新上传的二张广告图进行显示。</p>                       </div>       </if>		<div id="nav" class="mainnav_title">            <php>                 $getparam=$_GET;                 $getparam['activetab']='datalist';            </php>			<ul>				<a href="{pigcms{:U('House/house_nav_2list',$getparam)}" class="on">首页自定义导航列表</a>                <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('House/house_nav_add',array('block_type_id' => $block_type_id,'is_community_platform'=>1,'source'=>1))}','添加导航',850,580,true,false,false,addbtn,'add',true,'refreshPage');">添加导航</a>			</ul>		</div>		<div class="page_tips">图标建议尺寸：图片宽度建议为：150px，高度建议为：150px 平台已为你添加<span>{pigcms{$adver_count}</span> 张</div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>编号</th>							<th>分类名称</th>							<th>排序</th>							<th>状态</th>                            <th class="textcenter">操作</th>						</tr>					</thead>					<tbody>						<if condition="is_array($result['list'])">							<volist name="result['list']" id="vo">								<tr>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.sort}</td>									<td>									<if condition="$vo['status'] eq 1">										<font color="green">正常</font>									<elseif condition="$vo['status'] eq 0"/>										<font color="red">关闭</font>									</if></td>									<td class="textcenter">                                       <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('House/house_nav_edit',array('id'=>$vo['id'],'block_type_id' => $block_type_id,'is_community_platform'=>1,'source'=>1,'from_page'=>$_GET['from_page']))}','编辑导航信息',850,580,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('House/house_nav_del')}">删除</a>                                    </td>                                   								</tr>							</volist>						<else/>							<tr>                                <td class="textcenter red"  <if condition="($assign_type['type_2'] && $row_type neq single) || ($assign_type['type_11'] && $row_type eq single)"> colspan="5" <else/>colspan="4"</if>>列表为空！</td>                            </tr>						</if>					</tbody>				</table>                {pigcms{$result.pagebar}			</div>		</form>        </div>	</div><link rel="stylesheet" href="{pigcms{$static_public}kindeditor/themes/default/default.css"><script src="{pigcms{$static_public}kindeditor/lang/zh_CN.js"></script><script type="text/javascript" charset="utf-8">  layui.use('slider', function(){    var slider = layui.slider;    //渲染    var ins1 = slider.render({      elem: '#slideTest1',  //绑定元素      min: 0,      max: 50,      change: function(value){        $("#fillet_radius").val(value)      }    });    $(function (){      ins1.setValue($("#fillet_radius").val())    })    $("#fillet_radius").on('input keyup',function (e){      ins1.setValue(e.delegateTarget.value)    })  });      KindEditor.ready(function(K) {        var editor = K.editor({            allowFileManager : true        });        K('#label_img_up').click(function() {            editor.uploadJson = "{pigcms{:U('House/ajax_upload_pic')}";            editor.loadPlugin('image', function() {                editor.plugin.imageDialog({                    showRemote : false,                    imageUrl : K('#url3').val(),                    clickFn : function(url, title, width, height, border, align) {                        var img = K('#label_img_view');                        $('#label_img_div').show();                        img.attr("src",url);                        img.show();                        K("#label_img").val(url);                        editor.hideDialog();                    }                });            });        });    });   function saveNavSetData(){       var inputArr=$('#basicinfo_div .set_input').serializeArray();       console.log('inputArr',inputArr);       var set_input_title=$('#set_input_title').val()||'';       set_input_title=$.trim(set_input_title);       if(!set_input_title){            layer.alert('请填写标题！');            return false;       }       $.post("{pigcms{:U('save_village_nav_set')}",inputArr,function(result){            if(result.status != 1){                layer.alert('保存成功,请重试~ ');            }else{                layer.alert('保存成功！');            }        },'json');   }    function toggleNavTab(idd){        $('.tab_div').addClass('hide');        $('#'+idd).removeClass('hide');    }        $(function(){        $("#choose_color_box_labeltxt").click(function(){            change_labelcolor('choose_color_box_labeltxt','config_labelcolor');        });        $("#choose_color_box_block_bordertxt").click(function(){            change_labelcolor('choose_color_box_block_bordertxt','config_block_bordercolor');        });        $("#choose_color_box_block_bgtxt").click(function(){            change_labelcolor('choose_color_box_block_bgtxt','config_block_bgcolor');        });    });    function change_labelcolor(idd1,idd2){        window.showTopColorPanel("leftmenu_Viewpage_index",$("#"+idd1).offset().top,$("#"+idd1).height(),$("#"+idd1).offset().left,idd2,function(){            var bgcolor = $('#'+idd2).val();            $('.page-style').css('background-color', bgcolor);        });    }    function delsetimg(){       $('#label_img_div').hide();       $('#label_img_view').hide();       $('#label_img').val('');    }</script><include file="Public:footer"/>